		hooks = createdHooks;
		currentComponent.__hooks = createdHooks;
	}

	const hookList = hooks._list;
	const existingLength = hookList.length;
	if (hookIndex >= existingLength) {
		const createdState = {
			_pendingValue: EMPTY
		};
		hookList.push(createdState);
	}

	/** @type {import('./internal').ReducerHookState} */
	const hookState = hookList[hookIndex];
	hookState._reducer = reducer;

	if (hookState._component) {
		const queuedReturn = hookState._nextValue;
		if (queuedReturn) {
			return queuedReturn;
		}
		return hookState._value;
