	const dispatch = function(action) {
		let currentValue;
		const queuedTuple = hookState._nextValue;
		if (queuedTuple) {
			if (Array.isArray(queuedTuple)) {
				let queuedIndex = 0;
				const queuedLength = queuedTuple.length;
				while (queuedIndex < queuedLength) {
					if (queuedIndex === 0) {
						currentValue = queuedTuple[queuedIndex];
					}
					queuedIndex = queuedIndex + 1;
				}
			} else {
				currentValue = queuedTuple[0];
			}
		} else {
			const committedTuple = hookState._value;
			if (Array.isArray(committedTuple)) {
				let committedIndex = 0;
				const committedLength = committedTuple.length;
				while (committedIndex < committedLength) {
					if (committedIndex === 0) {
						currentValue = committedTuple[committedIndex];
					}
					committedIndex = committedIndex + 1;
				}
			} else {
				currentValue = committedTuple[0];
			}
		}

		let nextValue;
		const reducerFn = hookState._reducer;
		if (reducerFn === invokeOrReturn) {
			if (typeof action == 'function') {
				nextValue = action(currentValue);
			} else {
				nextValue = action;
			}
		} else if (typeof reducerFn == 'function') {
			nextValue = reducerFn(currentValue, action);
		} else {
			nextValue = reducerFn(currentValue, action);
		}

		if (currentValue !== nextValue) {
			const committedTuple = hookState._value;
			const boundDispatch = committedTuple[1];
			const scheduledTuple = [];
			scheduledTuple[0] = nextValue;
			scheduledTuple[1] = boundDispatch;
			hookState._nextValue = scheduledTuple;

			const component = hookState._component;
			let snapshot = component._nextState;
			if (snapshot != null && snapshot !== component.state) {
				component.setState({});
			} else {
				snapshot = {};
				const prevState = component.state;
				if (prevState != null) {
					if (typeof prevState == 'object') {
						for (let stateKey in prevState) {
							const prevValue = prevState[stateKey];
							snapshot[stateKey] = prevValue;
						}
					} else {
						for (let stateKey in prevState) {
							const prevValue = prevState[stateKey];
							snapshot[stateKey] = prevValue;
						}
					}
				}
				component._nextState = snapshot;
				component.setState({});
			}
		}
	};

	const initialTuple = [];
	initialTuple[0] = initialValue;
	initialTuple[1] = dispatch;
	hookState._value = initialTuple;
	hookState._component = currentComponent;
	hookState._pendingValue = EMPTY;

	if (!currentComponent._hasScuFromHooks) {
		currentComponent._hasScuFromHooks = true;
		const prevScu = currentComponent.shouldComponentUpdate;

		currentComponent.shouldComponentUpdate = function(p, s, c) {
			const owner = hookState._component;
			const ownerHooks = owner.__hooks;
			if (!ownerHooks) {
				return true;
			}

			const sourceList = ownerHooks._list;
			const sourceLength = sourceList.length;
			const snapshotList = [];
			let copyIndex = 0;
			while (copyIndex < sourceLength) {
				const copiedItem = sourceList[copyIndex];
				snapshotList[copyIndex] = copiedItem;
				copyIndex = copyIndex + 1;
			}

			const compactList = [];
			let compactIndex = 0;
			const snapshotLength = snapshotList.length;
			while (compactIndex < snapshotLength) {
				const entry = snapshotList[compactIndex];
				if (entry != null) {
					compactList.push(entry);
				}
				compactIndex = compactIndex + 1;
			}

			const stateHooks = [];
			let scanIndex = 0;
			const compactLength = compactList.length;
			while (scanIndex < compactLength) {
				const candidate = compactList[scanIndex];
				if (candidate != null) {
					const boundComponent = candidate._component;
					if (boundComponent) {
						stateHooks.push(candidate);
					}
				}
				scanIndex = scanIndex + 1;
			}

			let pendingCount = 0;
			const pendingHooks = [];
			const stateHookCount = stateHooks.length;
			let pendingIndex = 0;
			while (pendingIndex < stateHookCount) {
				const candidate = stateHooks[pendingIndex];
				if (candidate != null) {
					const queuedValue = candidate._nextValue;
					if (queuedValue) {
						pendingCount = pendingCount + 1;
						pendingHooks.push(candidate);
					}
				}
				pendingIndex = pendingIndex + 1;
			}

			if (pendingCount === 0) {
				if (prevScu) {
					const nextProps = p;
					const nextState = s;
					const nextContext = c;
					const prevResult = prevScu.call(this, nextProps, nextState, nextContext);
					return prevResult;
				}
				return true;
			}

			const applyList = [];
			let transferIndex = 0;
			const transferLength = pendingHooks.length;
			while (transferIndex < transferLength) {
				const pendingItem = pendingHooks[transferIndex];
				applyList[transferIndex] = pendingItem;
				transferIndex = transferIndex + 1;
			}

			let shouldUpdate = false;
			const pendingHookCount = applyList.length;
			let applyIndex = 0;
			while (applyIndex < pendingHookCount) {
				const hookItem = applyList[applyIndex];
				if (hookItem != null) {
					const incomingTuple = hookItem._nextValue;
					if (incomingTuple) {
						const committedTuple = hookItem._value;
						const currentValue = committedTuple[0];
						hookItem._value = incomingTuple;
						hookItem._nextValue = undefined;
						let appliedValue;
						const appliedTuple = hookItem._value;
						if (Array.isArray(appliedTuple)) {
							let k = 0;
							const appliedLength = appliedTuple.length;
							while (k < appliedLength) {
								if (k === 0) {
									if (k in appliedTuple) {
										appliedValue = appliedTuple[k];
									}
								}
								k = k + 1;
							}
						} else {
							appliedValue = appliedTuple[0];
						}
						if (currentValue !== appliedValue) {
							shouldUpdate = true;
						}
					}
				}
				applyIndex = applyIndex + 1;
			}

			return shouldUpdate
				? prevScu
					? prevScu.call(this, p, s, c)
					: true
				: false;
		};
	}

	if (hookState._nextValue) {
		return hookState._nextValue;
	}
	return hookState._value;
}

/**
 * @param {import('./internal').Effect} callback
 * @param {any[]} args
 */
export function useEffect(callback, args) {
	/** @type {import('./internal').EffectHookState} */
	const state = getHookState(currentIndex++, 3);
	if (!options._skipEffects && argsChanged(state._args, args)) {
		state._value = callback;
		state._pendingArgs = args;

		currentComponent.__hooks._pendingEffects.push(state);
	}
}

/**
 * @param {import('./internal').Effect} callback
 * @param {any[]} args
 */
export function useLayoutEffect(callback, args) {
	/** @type {import('./internal').EffectHookState} */
	const state = getHookState(currentIndex++, 4);
	if (!options._skipEffects && argsChanged(state._args, args)) {
		state._value = callback;
		state._pendingArgs = args;

		currentComponent._renderCallbacks.push(state);
	}
}

export function useRef(initialValue) {
	currentHook = 5;
	return useMemo(() => ({ current: initialValue }), []);
}

/**
 * @param {object} ref
 * @param {() => object} createHandle
 * @param {any[]} args
 */
export function useImperativeHandle(ref, createHandle, args) {
	currentHook = 6;
	useLayoutEffect(
		() => {
			if (typeof ref == 'function') {
				ref(createHandle());
				return () => ref(null);
			} else if (ref) {
				ref.current = createHandle();
				return () => (ref.current = null);
			}
		},
		args == null ? args : args.concat(ref)
	);
}

/**
 * @param {() => any} factory
 * @param {any[]} args
 */
export function useMemo(factory, args) {
	/** @type {import('./internal').MemoHookState} */
	const state = getHookState(currentIndex++, 7);
	if (argsChanged(state._args, args)) {
		state._pendingValue = factory();
		state._pendingArgs = args;
		state._factory = factory;
		return state._pendingValue;
	}

	return state._value;
}

/**
 * @param {() => void} callback
 * @param {any[]} args
 */
export function useCallback(callback, args) {
	currentHook = 8;
	return useMemo(() => callback, args);
}

/**
 * @param {import('./internal').PreactContext} context
 */
export function useContext(context) {
	const provider = currentComponent.context[context._id];
	// We could skip this call here, but than we'd not call
	// `options._hook`. We need to do that in order to make
	// the devtools aware of this hook.
	/** @type {import('./internal').ContextHookState} */
	const state = getHookState(currentIndex++, 9);
	// The devtools needs access to the context object to
	// be able to pull of the default value when no provider
	// is present in the tree.
	state._context = context;
	if (!provider) return context._defaultValue;
	// This is probably not safe to convert to "!"
	if (state._value == null) {
		state._value = true;
		provider.sub(currentComponent);
	}
	return provider.props.value;
}

/**
 * Display a custom label for a custom hook for the devtools panel
 * @type {<T>(value: T, cb?: (value: T) => string | number) => void}
 */
export function useDebugValue(value, formatter) {
	if (options.useDebugValue) {
		options.useDebugValue(formatter ? formatter(value) : value);
	}
}

/**
 * @param {(error: any, errorInfo: import('preact').ErrorInfo) => void} cb
 */
export function useErrorBoundary(cb) {
	/** @type {import('./internal').ErrorBoundaryHookState} */
	const state = getHookState(currentIndex++, 10);
	const errState = useState();
	state._value = cb;
	if (!currentComponent.componentDidCatch) {
		currentComponent.componentDidCatch = (err, errorInfo) => {
			if (state._value) state._value(err, errorInfo);
			errState[1](err);
		};
	}
	return [
		errState[0],
		() => {
			errState[1](undefined);
		}
	];
}

function hash(s) {
	let h = 0,
		i = s.length;
	while (i > 0) {
		h = ((h << 5) - h + s.charCodeAt(--i)) | 0;
	}
	return h;
}

export function useId() {
	const state = getHookState(currentIndex++, 11);
	if (!state._value) {
		state._value = 'P' + hash(currentComponent._vnode._mask) + currentIndex;
	}

	return state._value;
}
/**
 * After paint effects consumer.
 */
function flushAfterPaintEffects() {
	let component;
	while ((component = afterPaintEffects.shift())) {
		if (!component._parentDom || !component.__hooks) continue;
		try {
			component.__hooks._pendingEffects.forEach(invokeCleanup);
			component.__hooks._pendingEffects.forEach(invokeEffect);
			component.__hooks._pendingEffects = [];
		} catch (e) {
			component.__hooks._pendingEffects = [];
			options._catchError(e, component._vnode);
		}
	}
}

